INSERT INTO `tb_cafe` VALUES
(1,'223943927754','주포항','전라남도 함평군 주포로 388 ',35.0952,126.462,'여행/취미\n[함평 주포토요피크닉] 광주근교 나들이, 함평 바다 주포항\n순히 ・ 2025. 7. 23. 11:24\nURL 복사 이웃추가\n본문 기타 기능\n광주 근교 바다,\n함평 돌머리 해수욕장\n바로 옆에 있는 주포항에서\n매주 토요일마다\n\"주포 토요 피크닉\" 행사를\n진행한다고 해서 방문해봤다\n50m\n© NAVER Corp.\n주포항\n전라남도 함평군 주포로 388\n주포 토요피크닉 행사장은\n돌머리 해수욕장 들어가는 길에\n함평 포베오커피 바로 건너편에서\n진행하고 주차장도 있어서\n주차하기도 편했다\n입구에 이렇게\n종합 안내부스가 있어서\n궁금한 점은 여기에 문의해보면 될 것 같다\n인스타그램 팔로우 이벤트도 있고\n아이들이 좋아할만한 컬러링체험도 있었다\n주포항 생활권 어촌신활력증진사업 앵커조직(@hp.jupo) • Instagram 사진 및 동영상\n팔로워 382명, 팔로잉 507명, 게시물 72개 - 주포항 생활권 어촌신활력증진사업 앵커조직(@hp.jupo)님의 Instagram 사진 및 동영상 보기\nwww.instagram.com\n토요피크닉 행사에 관한 안내는\n주포항 인스타로 공지된다고 하니\n여기 들어가서 확인해보면 될 것 같다!\n그리고 안내부스에서\n어린이방문객을 위해\n무료로 풍선아트를 나눠주심!\n마침 앞에 있던 남자아이들이\n풍선칼을 받았다 ㅋㅋㅋ 귀엽\n그리고 한켠에는\n이곳 주민분들이 직접 만드신\n공예품도 전시되어있고 판매도 한다\n귀여운것도 많아서\n구경하는 재미도 쏠쏠했다\n그리고 직접 다 떴다는\n뜨개가방도 판매중!\n(가격 실화..? 실값도 안나올거같은데요..?)\n나도 뜨개질을 해보고싶은데\n예전에 한번 도전했다가\n영 소질이 없는 거 같아서 포기..\n행사장 안쪽에 푸드트럭도 있었다\n메뉴가 다양해서 골라먹는 재미!\n여름에 꼭 먹어야하는 옥수수랑\n내 최애 피카츄돈까스!\n옥수수는 말모 찰지고 맛있었다\n그리고 피카츄돈까스도 바삭하고 뜨뜻해서\n순삭 ㅎㅎ\n슬러쉬는 여쭤보니\n주변에 카페들이 많아서\n토요피크닉 행사장에서는\n운영하지 않는다고 하셨다 아쉽..\n버스킹 공연은 7시에 본격적으로 시작!\n확실히 여름이라 7시여도 날이 엄청 밝다\n그래도 낮보단 선선해서\n야외에서 관람하기 좋았다\n주포항 근처에\n주포한옥마을과 주포캠핑장이\n있어서 그런지\n버스킹 시간이 시작되니까\n사람들이 슬슬 모이기 시작했다\n그래도 행사장에 테이블이랑 의자들이\n세팅되어 있어서\n남는 자리에 앉으면 되는 듯?!\n주포 토요피크닉\n주포 토요피크닉 버스킹은\n노래, 댄스, 마술 등으로 구성되어있는데\n댄스는 옛날에 핫했던\n텔미, 허니도 나와서 내적댄스 엄청 춤ㅋㅋㅋ\n그리고 노을질때 노래버스킹을 들으니까\n딱 좋은 여름저녁을 즐길 수 있었다\n(자리에 앉아서 술도 드시던데\n운전만 아니었다면 나도 맥주 한캔 딱 하고싶었음)\n그리고 특히 마술 공연때는\n어린이들도 참여할 수 있는 시간도 있어서\n인기가 엄청났다\n특히 풍선을 들고 관객석으로 가서\n하나씩 나눠주는데\n완전 어린이들 광란..ㅋㅋㅋㅋㅋㅋㅋㅋ\n나중에 조카들 데리고 한번\n방문해봐야겠다\n마지막 밴드 버스킹까지\n토요일에 광주 근교\n함평 주포항에서 알차게 보냈다\n여름에 물놀이 가려고\n광주에서 가까운 함평 엑스포 물놀이장이나\n돌머리 해수욕장에 몇번 방문했는데\n저녁에 시간이 된다면\n주포항 토요피크닉까지\n방문해도 좋을 것 같다\n그리고 지금 함평에서\n물놀이페스타도 진행중이라고 한다!\n그나저나 노을 진짜 이쁘다\n뻔한 데이트가 지겨울 때 광주근교\n함평 주포항으로 나들이 와도 좋을 것 같다\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#광주근교\n#광주근교드라이브\n#광주근교나들이\n#광주바다\n#함평가볼만한곳\n#함평나들이\n#광주가볼만한곳\n#광주데이트\n#전남가볼만한곳\n#전남나들이\n#전남데이트\n#함평주포\n#함평돌머리해수욕장\n#함평물놀이장\n#포베오커피\n공감 19\n이 글에 공감한 블로거 열고 닫기\n댓글 20\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 11:24:00','관련 정보가 없습니다.'),
(2,'223943929227','데븡 해산물 식당 Seafood Đế Vương','1 Phan Tôn, Bắc Mỹ Phú, Ngũ Hành Sơn, Đà Nẵng 550000 베트남',16.0529,108.247,'travel diary\n🇻🇳 남친과 함께 다낭여행 1일차 🇻🇳 (새벽인천공항노숙/다낭환전/현지네일샵추천/기념품추천/빈펄호텔)\n몰랑뾰 ・ 2025. 7. 23. 11:26\nURL 복사 이웃추가\n본문 기타 기능\n🇻🇳 쉬는 날 빡세게 다녀온 다낭 여행 2박3일 기록 🇻🇳\n아침 6시 비행기 이슈로 출발 전날 퇴근하자마자\n막차 타고 공항 노숙하러 고고 ✨\n다음 날 6시 출발 뱅기라서\n체크인 시간까지 3시간 반만 버티면 돼서\n야식으로 밥 먹고 커피 수혈하며 열심히 기다리기 ㅎㅅㅎ\n생각보다 시간이 빨리가서 커피 마시며 기다리니\n체크인 시간이라 체크인 후다닥하고 뱅기 타러 ✈️\n졸려서 물을 못 사고 뱅기를 탔더니\n뱅기에서 파는 덤탱이 3,500원짜리 물을 사 먹어버림 😭\n4시간 30분을 달려 #다낭 도착 ✈️\n날씨가 너무 좋아버려 ☁️\n베트남은 처음인 남자친구 ㅎㅎ\n수많은 오토바이 보고 놀라는 중 🫢\n혹시몰라 #다낭스타벅스 에서\n키티 에디션 찾아봤는데 없어서 너무 슬펐다 🥺\n배고픈 배 부여잡고 원래 가려던 맛집이 문을 닫아서\n갑자기 온 #냐벱 식당\n사진보니깐 또 먹고싶다 😭\n진짜 너무너무 맛있다까지는 아니지만\n무난하게 맛있게 먹을 수 있는 식당이라 정말 배터지게 먹었는데\n여기 음료는 진짜 노맛… 너무너무 노맛 💦\n베트남오면 꼬오옥 먹는 #콩카페 코코넛 스무디 💖\n이건 왜 이렇게 맛있는지 서울에서도 사먹어 봤는데\n역시나 베트남에서 먹는게 짱맛 ✨\n베트남에서 유명한 환전소 중 하나인 #킴옌 에서\n환전도 두둑하게 하고 네일하러 네일샵으로 이동 ෆ\n다낭 올 때마다 방문하는 현지 네일샵 #네일바이얌 🩷\n여기 네일 지속력이 진짜 제거만 안하면\n두달은 넘게 유지될 정도로 짱이라 늘 다낭가면 가는 네일샵이다 ㅎㅎ\n역시나 꼼꼼하게 잘 해주셔서 너무 맘에 들었는데\n여긴 다 좋은데 위생은 생각하면 안됨 ㅎㅎ\n네일 가격은 총 418,000동으로 환화 약 22,000원인데\n화려함 + 연장 1개 가격이 대박… 🥹\n한국에서하면 적어도 10만원은 생각해야하는데\n이래서 베트남에서 네일은 필수 💖\n네일 너무너무 예쁘죠 ✨\n실물이 더 반짝이고 도톰하니 예뻐서 팁으로 100,000동 정도 줬는데\n팁이 전혀 아깝지않은 스타일과 유지력이라 기분이 쵝오였다 :)\nTMI로 이 네일도 제거하기 전까지 한달 반이나 버텨줌 ㅜㅜ\n#다낭한시장 에 선물 사러 방문했는데\n사람들 너무 많아서 깔려 죽을 뻔 💦\n한시장 갈 때마다 늘 노랑머리인 나를 기억해주는\n귀여운 언니 신발 가게에서 선물용 크록스도 구매했다 ㅎㅎ\n나보다 언닌데 볼 때마다 너무 어려보여서 내가 언니같아😂\n선물용으로 뜨개 인형도 구매했다 ㅎㅎ\n1층 과일가게 앞쪽에 위치해 있어서 저번에도 구매했었는데\n퀄이 너무 좋아서 조금 비싸지만 다 여기서 구매했다 💖\n태닝 키티도 새로 생겼길래 선물용으류 샀는데 너무 귀욤그잡채 ✨\n숙소에서 먹을 과일도 미리 포장하고 ~\n바리바리 싸들고 숙소로 컴백 ~\n여행 중에는 왤케 먹어도 먹어고 배고픈지\n배달로 반미도 시켜서 과일이랑 같이 먹었는데\n너무 짱짱맛 😭\n과일이 있다가 없어졌어요 ㅎㅅㅎ\n배 채우고 호텔 수영장에서 수영 했는데\n호텔 직원분이 사진도 찍어주셔서\n너무 행복한 시간을 보냈자나 ෆ\n귀여운 커플 옷 입고 이제 저녁 먹으러 💖\n데븡 해산물 식당 Seafood Đế Vương\n1 Phan Tôn, Bắc Mỹ Phú, Ngũ Hành Sơn, Đà Nẵng 550000 베트남\n해산물 음식 식당인데 너무 맛있어…\n가격도 저렴한데 너무너무 맛있어서\n다음에 다낭오면 또 갈듯한 곳 ㅎㅎ\n✨ 빠질 수 없는 야시장 타임 ✨\n역시나 사람들이 좀 많았는데\n밤이여도 더워서 조금만 구경하고 끝나따\n귀여운 장난감들 보는데\n분명 사면 후회할 거 같아 꾹꾹 참았다 ㅎㅎ\n노상 마사지도 받고\n게임도 해서 귀여운 (?) 인형도 득템했는데 바로 버림 ㅋㅋㅋㅋㅋㅋㅋ\n먹방 여행 맞아요 ^^\n야시장에서 숙소까지 걸어서 15분이라 소화가 되어버렸나\n아쉬워서 또 배달 먹었지요 ㅎㅎ\n배부르게 먹고 침대에 누워서 무한도전 보며\n하루 끄읕 :-)\n익숙하지만 남자친구와 함께라서 너무 행복했던\n다낭 여행 1일차 끝 💕\n태그\n#다낭\n#다낭스타벅스\n#냐벱\n#콩카페\n#킴옌\n#네일바이얌\n#다낭한시장\n#다낭여행\n#베트남다낭\n#다낭여행코스\n#다낭맛집\n#다낭카페\n#다낭기념품\n#여행블로거\n#일상\n#여행\n공감 19\n이 글에 공감한 블로거 열고 닫기\n댓글 5\n이 글에 댓글 단 블로거 열고 닫기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 11:26:00','관련 정보가 없습니다.'),
(3,'223943952523','바늘이야기 파주직영점','경기도 파주시 탄현면 법흥로 100-1',37.7766,126.706,'구경구경\n뜨개 힐링으로 핫토픽 선정 >< ! 파주 바늘이야기 후기\n누굴깡새우깡 ・ 2025. 7. 23. 11:43\nURL 복사 이웃추가\n본문 기타 기능\n위치바늘이야기 파주직영점\n블태기였다가 오랜만에 한 포스팅,\n\'요즘 힐링 아이템_ 뜨개\' 가 핫토픽에 소개되었다 ><\n끼야호 ~\n그동안 핫토픽 모르고 살았는데 영광스럽고만 ^^!\n조회수도 별로 안 높았는데....\n선정기준이 뭔지 잘 모르겠지만\n앞으로도 더 열심히 뜨개와\n포스팅을 해야겠다는 다짐을 했다 🧐\n오늘의 포스팅은 이번 주말에 다녀온\n바늘이야기 파주직영점 방문 후기다\n바늘이야기 파주직영점\n경기도 파주시 탄현면 법흥로 100-1\n바늘이야기 파주직영점\n경기 파주시 탄현면 법흥리 100-1\n운영시간 : 화-일, 오전 10시부터 저녁7시\n매주 월요일 정기휴무\n내가 파우치나 가방을 만들었던 도안과 실이\n바늘이야기에서 판매되고 있는 제품인데\n바늘이야기 오프라인 매장에서는\n실물로 직접 보기도 하고,\n카페에서 뜨개를 할 수도 있다고 해서\n꼭 가보고 싶었다 0.0 !\n바늘이야기는 파주직영점과 연희점이 있는데\n연희점은 친구랑 지하철 타고 갈 수 있어서 킵해 놓고\n혼자 가기 어려울 것 같은 파주직영점을\n남편한테 가자고 했다 ㅎㅎㅎ!\n아무래도 대중교통보다는\n차로 이동하기 편한 위치라서 그런지\n주차할 수 있는 공간이 많았다\n벽장 가득히 빼곡한 콘사가 인상적인\n뜨개 카페 _ 바늘이야기\n1층 매장에서는 실과 바늘, 부자재들을 살 수 있고\n2층, 3층은 커피를 마시며\n뜨개를 즐길 수 있는 카페공간이다\n실의 종류와 색상이 다양해서\n실 구경하는 것만으로도 재밌다\n뜨개 초보인 나는 어떤 실로 먼저 시작하면 좋을지\n뭐부터 떠볼지 고민이었는데\n직원분께 물어보니 추천을 해주셨다\n완성된 완제품들의 색상/크기/무게들을\n볼 수 있다는 점도 좋았다 ㅎㅎ!\n구경하다보면 만들고 싶은 거 엄청 많다\n앞으로 무진장 바쁠 예정 ㅜ !\n이 실버 가방은 여름에 잘 어울릴 것 같아서\n내년 여름에 떠보기로 -!\n버터벨 파우치를 뜨고 남은 실로 뭘 만들까\n고민하고 있는 와중에 발견한\n코튼10 카드지갑 0.0!\n투박하면서도 귀여움이 묻어나서\n만들어보려고 관련 부자재도 장바구니에 담았다\n집에 실 95g 남앗었는데\n카드지갑 만들고도 또 남았다 ㅎㅎ!\n내가 만든 카드지갑 ♥\n뜨개는 같은 모양 반복이라 쉬웠는데\n똑딱이 버튼을 바늘질하는게 귀찮고 어려웠다 ㅜ\n뜨개는 좋아도 바느질을 못해모태 !\n여기에 돗바늘, 라벨 등 뜨개 부자재를\n넣어다니는 용도로 사용할꼬다. 후후\n옷은 왠지...고수의 영역 ....\n넘사벽이라 봐도 욕심이 안나여....ㅜ;\n바늘이야기에 각종 부자재들도 엄청 다양하게 많다\n동대문 부자재시장 다시 한번 가고 싶었는데\n여기서 한방에 해결할 수 있다 0.0!\n귀여운 키링과 단추들도 짱 많고 ~\n요렇게 도안도 판매되고 있다\n이것저것 들어보며 내가 만들고 싶은 거를\n일단 두 가지만 골라왔다\n만원 당 스탬프 한 장씩 찍어줌 ㅎㅎ!\n영차영차~\n이제 뜨개질 해보러 2층 카페로 고고 ~\n커피와 케이크, 간단한 제과류가 있는\n2층과 3층은 뜨개 카페 -!\n근데 중요한 건 이런 게 아니고....\n이 초록초록한 옥상 잔디밭 뷰를 보며\n안락의자에 앉아 편하게 바느질을 할 수 있다는 거 !\n안쪽으로 더 다양한 자리가 많아보였는데\n우린 그냥 이 자리 보자마자\n여기에 눌러 앉았다 ㅎㅎㅎ\n커피도 마시고 가방도 완성하고 !\n바늘이야기 파주점까지 집에서 멀어서\n왕복3시간 걸렸지만\n그래도 재밌고 행복한 여운이 남는 하루였다 ^0^!!\n태그\n#바늘이야기파주점\n#바늘이야기파주주차\n#바늘이야기가방\n#바늘이야기\n#바늘이야기카페\n공감 30\n이 글에 공감한 블로거 열고 닫기\n댓글 18\n새 댓글\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 11:43:00','관련 정보가 없습니다.'),
(4,'223943965760','카페호누','경상북도 경주시 갓뒤길 12-5 카페호누',35.8706,129.218,'게시판\n카페가 문을 닫는 이유, 그 안에서 배우는 살아남는 법칙\n커피내리는 남자 ・ 2025. 7. 23. 11:54\nURL 복사 이웃추가\n본문 기타 기능\n“맛은 기본, 결국은 태도와 방향이 브랜드를 살린다.”\n1. 요즘 왜 이렇게 카페가 자주 바뀔까?\n요즘 길을 걷다 보면 눈에 띄게 자주 바뀌는 간판이 있습니다.\n어제까지 감성 가득한 카페였던 자리가 어느 날은 폐업 정리 중,\n그리고 한 달 후엔 새로운 브런치 카페로 바뀌어 있곤 하죠.\n통계에 따르면 신규 카페의 70% 이상이 3년을 버티지 못한다고 합니다.\n커피 수요는 꾸준하지만, 그만큼 공급도 넘쳐나는 시장.\n그 안에서 살아남는다는 건 단순히 맛있는 커피 한 잔만으로는 부족하다는 뜻이죠.\n2. 카페가 문을 닫는 이유 – 우리가 보지 못한 진짜 사연들\n겉으로 보기엔 예쁘고, 메뉴도 괜찮고, 분위기도 그럴싸한데\n왜 문을 닫을까?\n✔ 1위. 유동인구만 믿고 입지 선정\n– 보여야 팔린다는 말은 맞지만, \'보이는 곳\'과 \'머무는 곳\'은 다릅니다.\n– 접근성, 주차, 동선, 고객의 행동패턴까지 계산하지 않으면 실패 확률 급증.\n✔ 2위. 브랜딩이 없는 가게\n– 맛있어도, 예뻐도, ‘기억에 남지 않으면’ 다시 오지 않습니다.\n– 이름, 분위기, 메뉴, 메시지... 하나로 연결되는 정체성이 필요합니다.\n✔ 3위. 운영자의 체력과 정신력이 먼저 무너짐\n– 직접 운영하는 자영업자의 일상은 매일이 전쟁.\n– 체력, 마인드셋, 고객과의 소통, 수익 계산... 모두를 다 감당해야 하는 현실.\n✔ 4위. 홍보의 어려움\n– 좋은 건 알리기 전까진 아무도 모릅니다.\n– 오프라인 장사는 결국 온라인과 함께 가야 살아남는 시대입니다.\n3. 그럼에도 불구하고 살아남는 카페들의 공통점\n그렇다면 지금도 사랑받고 있는 카페들의 공통점은 뭘까요?\n🌿 진짜 브랜드가 있는 곳\n단순히 메뉴가 아니라, \'이곳은 이래서 좋다\'는 이유가 분명합니다.\n그게 콘셉트든, 사람의 태도든, 커피에 담긴 철학이든…\n📌 꾸준한 고객 커뮤니케이션\n손님과의 소통, 피드백, 그리고 그 안에서 끊임없이 개선하는 태도.\n🧭 방향이 흔들리지 않는 운영자\n수많은 유혹과 변화 속에서도 ‘우리는 이걸 잘하고 싶다’는 중심을 지켜냅니다.\n가끔은 느리지만, 단단하게 성장하는 가게가 오래갑니다.\n4. 카페호누는 어떻게 살아남고 있을까\n저희 카페호누도 사실 평범한 골목 카페에서 시작했습니다.\n주차 공간이 부족하고, 유동인구가 많은 자리도 아니었습니다.\n하지만 시작부터 방향은 분명했습니다.\n☕ 우리는 직접 로스팅한 커피로 정직하게 승부한다.\n🌺 하와이 감성을 담은 공간에서, 소소한 쉼을 제공한다.\n🐢 손뜨개 소품과 수제 디저트로 진심을 전한다.\n홍보는 쉽지 않았지만, 블로그와 인스타그램, 고객과의 꾸준한 대화를 통해\n조금씩 저희의 진심을 알리기 시작했고,\n단골이 생기고, 팬이 생기고, 브랜드가 만들어졌습니다.\n카페호누로스팅\n재생\n1\n좋아요\n1\n00:19\n\n카페호누로스팅\n5. 살아남는 법칙은 결국 ‘진심’\n문을 닫는 이유는 다양하지만,\n살아남는 법칙은 의외로 단순합니다.\n“좋은 방향을 가지고, 흔들리지 않고, 진심을 담아 지속하는 것.”\n이건 누구에게나 가능한 듯 보이지만,\n매일을 버텨야 하는 자영업자에게는 결코 쉽지 않은 일입니다.\n그래서 저희는 매일 생각합니다.\n오늘도 손님 한 분에게 우리가 어떤 인상을 남겼는지,\n우리가 만든 공간이, 커피 한 잔이,\n누군가에게 작은 쉼표가 되었는지를.\n🐢 마무리하며\n혹시 요즘, 자주 바뀌는 간판들을 보며\n“왜 저 가게는 안됐을까?”라는 생각을 해보셨다면,\n그 속에는 이 작은 글에서 전한 이야기들이 담겨 있을지도 모릅니다.\n카페호누는 오늘도 골목 어귀에서 묵묵히 한 잔의 정성을 준비하며,\n앞으로도 오래 기억될 수 있는 공간이 되기 위해 노력하겠습니다.\n네이버 지도\n카페호누\nnaver.me\n50m\n© NAVER Corp.\n카페호누\n경상북도 경주시 갓뒤길 12-5 카페호누\n예약\n궁금할 땐 네이버 톡톡하세요!\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#카페브랜딩\n#카페폐업이유\n#살아남는카페\n#카페운영팁\n#카페창업\n#골목카페\n#카페호누\n#경주카페\n#황성동카페\n#하와이감성카페\n#로스팅카페\n#진심이있는카페\n공감 3\n이 글에 공감한 블로거 열고 닫기\n댓글 1\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 11:54:00','뜨개질, 있음  \n손뜨개, 있음  \n소품, 있음  \n디저트, 없음  \n접근성, 없음  \n주차, 없음  \n동선, 없음  \n고객의 행동패턴, 없음  \n주차 공간, 없음  \n유동인구, 없음'),
(5,'223944047329','시옷지읒','부산광역시 동구 초량로 112 1층',35.1195,129.031,'▶eat,etc\n부산 원데이클래스 시옷지읒 데이트코스 책갈피만들기\n찌롱이 ・ 2025. 7. 23. 13:09\nURL 복사 이웃추가\n본문 기타 기능\n간만에 찾은 낭만의 도시 부산!!\n이번 여행은 부어라 마셔라 놀고만 싶진 않았기에\n남길수있고 체험가능한 원데이클래스를 진행하기로~\n그 중 우리는 책갈피 원데이 클래스\n#시옷지읒 방문했다\n부산 동구 초량로 112 1층\n오전11시~오후8시\n예약, 반려동물 동반, 무선 인터넷\n0506-623-6949\n⬇️인스타그램⬇️\n시옷지읒(@siotzieut) • Instagram 사진 및 동영상\n팔로워 264명, 팔로잉 84명, 게시물 130개 - 시옷지읒(@siotzieut)님의 Instagram 사진 및 동영상 보기\nwww.instagram.com\n외관도 귀염뽀짝하게 있던\n부산 공방 시옷지읒\n#부산데이트\n#부산원데이클래스\n#부산가볼만한곳\n처음 온 사람들도 편하게 만들어주신\n사장님의 성향덕에 편안히 배울수있던\n부산 원데이클래스 시옷지읒\n손재주가 없는 초보여도\n전~혀 걱정안해도될듯했음 !\n공간 자체가 너무 아늑하고 감성 그 자체🤎\n따뜻한 조명에 들어서자마자\n기분이 좋아지더라\n선택이 어려운 사람들을 위하여\n사장님이 미리 조합해둔 실패없는\n조합이 준비돼있지만\n내가 직접 원하는 색조합도 가능하니\n마음 내키는대로 선택하면 댐!\n금손 사장님의 작품들도 구경하고\n영감을 얻어보고자 이리저리 구경 또 구경ㅎㅎ\n구경하는데 왜 힐링이 되는 건지 !? 🙊\n실력이 어마무시하신,,\n특히 소품샵에서 파는 저퀄리티가 아닌\n제품들이 진짜 짱짱하고 단단했음\n물욕 참느라 아~주 힘들었다\n그렇게 정신 차리며 친구와 골라 온\n푸릇푸릇한 초록실들ㅎㅎㅎㅎ\n실들을 골라오면 사장님이 차근차근\n책갈피 첫 코바늘이되는 부분을 설명해주신다!\n사실 손뜨개는 어릴적부터\n재주가 없었던터라 잘할수있을까?했는데\n꼼꼼히 설명해주시기도하고 옆에서\n팁도 알려주셔서 혼자서 척척 해낼수있던\n책갈피원데이클래스 🩶🩶\n간만에 집중 타임을 가진ㅋㅋㅋ⫬\n요즘 스트레스도 부쩍 높았는데\n잡생각은 없어지고 온전히 뜨개에만 열중했다\n커피도 챙겨주셔서 목이 탈때쯤\n카페인수혈도 해주며 열정 업업 !\n기대보다 더 재밌었던 책갈피 원데이 클래스\n생각보다 신경쓸것도 많고\n조금만 급하게 해버리면 꼬여버리니\n급한 내 성향을 다운 시키기 좋았던 수업이랄까?\n친구와의 방문도 좋지만 아이들체험에도\n좋을듯한 부산 원데이클래스!\n단시간에 이렇게나 귀여운 책갈피와\n키링을 만들었따~~~~\n결과적으로 너무나 만족했던\n부산 시옷지읒 원데이클래스 !\n친구나 지인에게 추천하고 싶은 곳 >.<\n책갈피 클래스 이 외 다른 원데이클래스도\n진행하고 있으니 부산여행 가볼만한곳을 찾는다면\n시옷지읒 방문해보시길 ~~~!\n⬇️위치⬇️\n50m\n© NAVER Corp.\n시옷지읒\n부산광역시 동구 초량로 112 1층\n예약\n태그\n#시옷지읒\n#부산데이트\n#부산원데이클래스\n#부산가볼만한곳\n#부산공방\n#부산데이트코스\n#부산갈만한곳\n#부산여행\n#부산여행코스\n#부산여행코스추천\n#부산시옷지읒\n#원데이클래스\n공감 3\n이 글에 공감한 블로거 열고 닫기\n댓글 쓰기\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 13:09:00','손뜨개, 있음  \n뜨개질, 있음'),
(6,'223944062628','용다리','Đ. Nguyễn Văn Linh, Phước Ninh, Hải Châu, Đà Nẵng 550000 베트남',16.0612,108.23,'25\' 다낭\n[다낭 여행] 다낭 한시장 + 한시장 쇼핑리스트\n여진 ・ 2025. 7. 23. 13:30\nURL 복사 이웃추가\n본문 기타 기능\n위치한시장\n배부르게 먹고 나와서\n한강 구경하기\n강바람이 시원하게 불었다.\n(물론 약간의 습도는 감안....😁)\n멀찍이 용다리도 보였고\n용다리\nĐ. Nguyễn Văn Linh, Phước Ninh, Hải Châu, Đà Nẵng 550000 베트남\n용다리에서는 매주 금,토,일에 불쇼가 열리는데\n여태 한번도 보지못함...😅\n한강 근처에 공원처럼 꾸며진 이곳은\n밤에 와서 보면 야경이 장관일 것 같다 👍\n친구랑 사진 적당히 남기고\n원래의 목적인 한시장으로 향했다.\n대망의 한시장, 두둥두둥\n한시장\n119 Trần Phú, Hải Châu, Đà Nẵng 550000 베트남\n한시장에 정말 다양한 품목들이 판매되고 있지만\n나는 필요한 몇몇 품목만 사기로함!\n한시장 쇼핑리스트\n1. 크록스\n시세표가 카페나 인터넷에 돌아다닐 뿐 아니라\n현지 시장에도 떡하니 걸려있다 😅\n거의 저정도 선에서 구매가 다 이루어지기 때문에\n여러 켤레 사서 할인 받는 것을 추천!\n나는 256번 가게에서\n나는 남자 크록스 기본 1, 샌들 1, 지비츠 4 세트 구매함\n62만동에서 2만동 깎아서 60만동 계산했다.\n더 많이 사거나 금액이 애매하면 조금씩 할인 더 받길\n2. 방도 & 머리핀\n집에 있는 비똥이에 감아주려고 산 방도\n머리핀은 방도 사러갔다가 구경하면서\n친구랑 같은 걸로 맞춰서 샀다.\n방도는 여러 브랜드 짭이 있으니 맞춰서 사고\n에*메스는 15만동 정도라고 한다.\n3. 뜨개가방 & 카피바라 (뜨개) 인형\n니트 가방을 사고 싶었는데\n처음 갔던 집에서 딱히 눈에 들어오는게 없어서\n주인 언니 고생만 시키고 카피바라만 샀는데\n2층에서 저 무늬 있는 니트가방을 발견한 것!\n근데 2층은 넘모 비쌌다.. 사람은 많았는데\n혹시나하고 1층에 72번 언니한테 갔는데\n세상에 가격이 훨씬 저렴했음!!!\n가방 사려는 분들 72번 언니한테 가세요 🧡\n4. 마그넷\n마그넷은 호이안에서 고퀄로 따로 사기로하고\n다낭에서는 한시장이 저렴하다고 해서\n조금만 구입했다.\n저기에 미니 카피바라까지 같이 구입했는데\n가방에 달고 다니다가\n어느새 사라져버렸다는 슬픈 사연....😂😂\n마이멜로디 카피바라였는데 허허허\n5. 원피스\n원피스는 안감이 있냐 없냐에 따라\n가격이 조금 달라지는거 같고\n기본 원피스는 8만동~10만동 사이였다.\n패턴 고르면서 이리저리 정신 없이 다니다가\n급하게 구매해서 몇 번에서 샀는지 기억이 안남..\n그래도 저렴하게 잘 사서 잘 입고 다녔다 😁\n그외에도 티셔츠나 속옷, 잠옷 등등\n정말 별의 별 제품들이 많은 한시장\n내부는 매우 더우니 오래 머무르지 않고\n미리 어디에 가서 무엇을 살지 정하고\n빠르게 쇼핑한 후 탈출하는 것을 추천!\n카페나 인터넷에 한시장 지도 및 시세표 등등이\n많이 돌아다니고 있으니\n미리 공부 많이하고 가서 저렴하게 겟 하시길 😁😁\n짭의 천국 베트남은\n간판 마저도 넘나 웃겼다.\n얼마전에 단속 때문에 문 닫고\n시끌시끌했다고 하던데\n간간이 영업하는 곳들이 있는 것 같으니\n잘 찾아다녀서 득템하시길 ㅎㅎㅎ\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#다낭한시장\n#한시장\n#한시장쇼핑리스트\n#한시장크록스\n#다낭한시장크록스\n#다낭한시장시세\n#다낭한시장추천가게\n#다낭용다리불쇼\n#한시장카피바라\n#한시장크록스추천\n#한시장크록스가격\n#다낭크록스가격\n#다낭크록스\n#한시장방도\n#한시장추천리스트\n#한시장니트가방\n#한시장가방\n#다낭쇼핑리스트\n#다낭한시장쇼핑리스트\n#다낭한시장쇼핑\n#다낭쇼핑\n#한시장쇼핑\n#다낭여행\n#베트남여행\n공감 3\n이 글에 공감한 블로거 열고 닫기\n댓글 2\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 13:30:00','관련 정보가 없습니다.'),
(7,'223944076292','place1 3','서울특별시 종로구 팔판길 23 Place 1-3',37.5829,126.981,'일상모음\n25년 6월\nchotree ・ 2025. 7. 23. 13:34\nURL 복사 이웃추가\n본문 기타 기능\n합동 프로젝트로 이모티콘 구상 중\n근데 이제..\n아이디어도 쟤가 내고 그림도 쟤가 그리고\n나는 관리 감독만 하는 ^^ ?\n이동네 추억의 맛집 같은 곳이라는데..\n...어.... 어딘지 언급은 하지 않겠습니다 ㅎ\n참치 김밥은 맛있었음\n저녁은 우리집 근처에 있는 치킨집 !\n지나가면서 맨날 가보고 싶었는데\n이날 내가 다녀오고 나니 폐업했다 (오랜 기간 영업했던 곳)\n나 진짜 무슨 주호민이라도 되는 건가....\n근처 복권방도 나름 유명했는데 내가 다녀오니까..\n고새 없어졌어요 ^^\nㅋㅋㅋㅋㅋㅋㅋㅋ 참나 ~\ncho호민 이라고 불러주세요\n고급진 냐옹이와 함께한 위블로 화보를 구경하며\n일단 영화 보러 고고..\n심야로 !\n요즘 사람 붐비는 곳에 가는게 병적으로 싫어서\n영화는 거의 심야로만 본다 ㅎㅎ...\n난 MI의 빅팬은 아니지만 시리즈를 꽤 열심히 챙겨보긴 함\n이번 편은 기대이상이었고 유종의 미를 잘 거둔 듯 ?\n하지만 이제 이런 액션은 은퇴하세요 톰 아저씨....\n-\n요맘 때만 반짝 볼 수 있는 새끼 오리들\n엄마 오리 졸졸 따라다니는 것이 졸귀이다.\n아기 동물들을 보면 뭐랄까.. 맘이 스르륵 녹음..\n물론 더욱 졸귀인 쿤\n픽업 주문한 음식 동생이 받으로 간 사이에\n쿤이랑 셀카 찍기 시도하기.\n저기, 혹시 렌즈 좀 봐줄 수 있겠니\n-\n쉬는 날, 편하게 할 일 할 카페를 찾다가\n그팩 커넥트라운지를 와보았다.\n평일에만 열다보니 사람이 엄청나게 많지는 않다\n그래서 인구 밀도가 꽤나 쾌적 -\n비치되어 있는 책들은 자유롭게 볼 수 있다.\n넘 재밌었던 피로사회\n쾌적한 공간에서 갖는 me타임 너무 행복쓰\n-\n#아가젤라또\n이어서 나와의 성수동 데이트 시간을 가짐\n역에서 내림과 동시에 기빨리기 시작....\n인간 너무 많아.. 살려줘..\n올영에서 피도 뚝뚝 떨어지길래 당 채우러왔다...\n성수는 위험한 곳이야 ㅠㅠ....!!!!!\n딸기 소르베, 애플망고 소르베 + 바질우유\n아이스크림 먹으니까 기분 좋아짐 ^___^\n가게 앞 의자에 앉아서 먹었다.\n아 MZ 감성 빡세다..\n작정하고 당 섭취하는 날.\n이날은 구체적으로 \'추러스\'가 너무 먹고 싶었다.\n양심 상 좀 멀리멀리 걸어왔다.\n아니 근데 나는 이렇게 클 줄은 몰랐어요....\n꽤 맛있었는데 반 이상 남김 아깝 ㅠ\n책 좀 읽고 시간 보내다가 ~\n예약해둔 롬앤 조색 클래스 고고고\n브라운톤 상의가 찰떡인 것으로 보아\n나는 가을인간인 것이 확실하다.\n립밤 타입으로 2개 만들었다 ㅎ.ㅎ\n나이프로 요리조리 섞으면서 내 취향 찰떡 컬러를 만들었다 !\n색채수업 듣던 시절도 생각나고 재밌었다.\n하나는 코랄 느낌이고 하나는 베이지 !\n집으로 돌아오자마자 부랴부랴 테니스 레슨 고\n나는 언제 야외 코트에 나갈 수 있을까..\n-\n창문 밖으로 종종 눈 마주치는 고양이.\n왜 요즘은 잘 안 오니 ㅜㅜ\n자연의 색 !\n이날은 H의 식탁 구매를 위해 이케아에 왔다.\n원래 좌식 식탁 썼는데 활용도가 너무 떨어져서\n결국 당근으로 팔고 새로운 놈을 사기로 했다.\n역시 자취 1년 동안은 시행 착오의 연속이다.\n일단 밥부터 먹고 시작이요 -\n닭다리 치킨이랑 닭다리살 스테이크는 필수.\n돈까스라 김볶도 평타는 했다 ㅋㅋㅋ\n개인적으로 찜해둔 식탁\n이케아치고 가격대가 좀 있었는데 다리 모양이 예뻤다.\n근데 막상 사려는 물건들은 다 품절 상태이거나\n실제로 보니 너무 싼티 나는 느낌.. ㅠ\n이케아는 제품 별로 퀄리티 편차가 좀 큰 것 같다.\n어떤 건 너무 괜찮은데 어떤 건 너무 구리고..\n그래서 반드시 눈으로 보고 사야됨\n그리고 그의 눈에 띄어버린 아기 허스키....\n결국 입양해 가심\n이름도 지어줌\n= 미숙이 = 미니 + (허)숙희\n-\n원 오브 베프의 결혼식 ~\n손하트 어떻게 하는지 모르는 사람 = 나\n슬림 드레스가 세상에서 가장 잘 어울리는 신부였다 ~\n정신차려보니 나만 미혼이네 ?\nㅋㅋㅋㅋㅋ 뭐.. 어떻게든 되겠지.. 허허허\n잘 살아라 칭구야 !\n여러모로.. 결혼에 대한 진지한 생각을\n도저히 미룰 수가 없는 때가 왔다 이거야 ~\n-\n회사에서 첨으로 플리마켓을 했는데\n셀러 신청해서 엄마가 만든 뜨개 가방 잔뜩 팔고 왔다 ㅋㅋㅋ\n효도카드 하나 적립 ^^*\n사람이 넘 많아서 조금 부끄러웠지만 나름 재밌는 경험이었음 ㅎ\n-\n새로운 가방 개시한 날 !!!!!!!\n에비수 매장에서 보고 첫눈에 반했는데 아른거려서 걍 삼\n나일론이라 비오는 날 들어도 문제 없어서 넘 좋다.\n아빠가 요즘 어디 고기 잡으로 다니냐고 놀렸지만 ~\n아주아주 잘 들고 다니는 중 !\n#르메르필트포춘 #르메르네트백\n#소이빙수\n이 동네 모든 사람들이 다 여기 빙수 먹으러 오는 듯 ^o^\n다행히 우리는 딱 한 자리 남아서 바로 착석하고 주문했다.\n생딸기는 아니지만 나름의 매력있는 딸기 샤베트 ?\n치즈케이크 추가해서 먹으니까 아주 맛남\n#쿠시카츠쿠시토라\n나도 감자 샐러드 집에서 해먹고 싶다..\n근데 감자 껍질 벗기는 게 너무 귀찮아 ^^...!!\n맛있는 거 먹으면서 앞으로 이 관계 어떻게 해야할지 (?)\n에 대한 대화를 나누기 시작했는데...\n\"초현실주의인 H & 초초불안핑 나\"의 조합이라\n첨엔 앞이 다소 캄캄해지는 느낌... ㅎ.ㅎ ?\n#카페라포르\n그래도 우리 둘은 이성적으로 대화를 잘 하는 편이라\n건설적인 대화를 건강하게 잘 하고 있음에 다행이라고 생각했음\n얘기 하다보면 어렵다고 생각했던 부분들에 대해서\n생각보다 별 거 아니다 ! 라고 생각되기도 하고..\n-\nH가 좀 뭐랄까 사회적 시선에 무관심한 편이라\n종종 나의 다소 과한 기준점들을 흔드는 느낌이 있다.\n그런 순간들을 마주할 때 약간 가치관의 혼란이 오는데..\n그것이 불편하면서도 나름대로 나에게 도움이 된다고 생각한다.\n\'이래야 돼! 이렇게 살아야해!\'에 매몰되어 정병 오는 것을 막아줌 ㅋ\n넘 좋아하는 애플크럼블 !\n잘 파는 곳이 없어서 슬픈데 찾았다 !\n카페 바로 건너편에는 테니스장이 보였다.\n경기 남부(특히 분당)은 테니스장이 정말 많은 편이다.\n이제 내게 필요한 것은 야외 코트에서 공 칠 수 있는 실력\nㅋ.... 한 1년은 더 있어야 할 듯 ㅠㅠ !!!\n저녁까지 이어진 대토론의 현장 ^.^......\n거의 뭐 미래설계 워크샵이다 워크샵.\n어쩌다 보니까 서로 가진 돈 다 깠는데\n본인 생각보다 내가 모은 돈이 많아서 동공지진 심하게 온 H\nㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n나 23살부터 지금까지 6개월 쉬고 쭉 일했다고 ^^..\n그러면서 자기반성 시간을 가지셨는데,\n아니 걍 내가 너보다 최소 3년은 더 일했으니까 당연한 거야..\n-\n회사에서 성심당 팝업해가지고 가려고 했는데\n빌어먹을 에어컨 청소 일정이 엉망이 되어버리는 바람에\nH가 대신 나의 튀소를 구매해주러 가줬다.\n그와중에 순번 마지막이라고 사진 찍혔다고 함 ㅠ\n참고로 그는 사진 찍히는 걸 세상에서 제일 싫어함\n어떤 표정이었을지 상상가서 넘 웃겼음 ㅠㅠㅠㅠ\n감사의 의미로 회사로 데릴러 갔다 ㅎ.ㅎ\n근데 집으로 돌아오는 길에 신호위반한 경찰차때문에\n개큰 교통사고 날 뻔함... 식은땀 흘리고 손 벌벌 떨면서 옴\n진짜 한 1-2초 사이에 이미 나는 머릿속으로\n한문철에 사고 영상 보냈고 차 폐차 시키고 있었음\nㅋㅋㅋㅋㅋㅋ 안돼 ㅠㅠ 내 보물 1호 ㅠㅠㅠ\n현재 내 신체와 차 모두 멀쩡함에 감사할 따름.\n이날 이후로 또 한 번 경각심 갖고 안전 운전 중이다.\n그건 그렇고 튀소는 맛있어 ~~~~\n놀란 가슴 달래며..\n동생이 준 기프티콘으로 오랜만에 고추바사삭 먹었다.\n오랜만에 먹으니까 진짜 맛있구만\n-\n같은 동네 사는 팀원분으로부터 스위치를 당근했다 !\n원래 이런 게임은 잘 하지 않는 편인데\n요즘엔 날씨때문에 주말에도 집을 나가기 싫어서\n집에서 놀 수 있는 여러가지 것들을 마련하고자 ㅎㅎ\n#파파라구\n엄청 저렴하게 넘겨주셔서 감사의 의미로 점심 사드렸다.\n라구 라자냐는 넘 맛있었고 피자는 내 기준 평범했다.\n#키로베이커리 의 존맛탱 소금빵도 소개해드리고 !\n구성이 아주 알차다 알차.\n약간 충동구매이긴 했는데 사길 너무 잘함..\n매 주말마다 열심히 하는 중 ㅋㅋㅋㅋ\n-\n오랜만에 #서랍 으로 밥 먹으러 왔다.\n전팀에서 같이 일했던 분들이랑 옴\n타로도 봤구요 ㅎㅎㅎㅎㅎ\n요즘 우주의 기운들이 자꾸 대학원 가라고 함....\n으아.. 트리 돈 없어.....\n저녁엔 젤다 잠깐 깔짝거려봤는데..\n나 진짜 너무 못해서.. 너무 웃김......ㅋㅋ\n계속 높은 곳에서 아무 생각 없이 떨어져서 죽고\n몬스터 나오면 때려죽일 생각을 해야되는데 도망가다가 죽고\n퀘스트가 뭔지도 모르고 길도 못 찾음\n걍 총체적 난국 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n-\n뮤지컬 보려고 종로 방문 ~\n오징어게임 팝업하고 있었다.\n영희 덥겠다....\n서울시 마스코트로 도배된 버스\n컬러가 예쁘군\n삼청동 ~ (더워 죽을 거 같음)\n#그레이맨션\n키링 만들려고 왔는데 원하는 모듈이 딱 없어서 ㅠㅠ\n아쉽지만 다음을 기약하며 빈 손으로 나왔다.\nplace1 3\n서울특별시 종로구 팔판길 23 Place 1-3\n그냥 가는 길에 보여서 들어옴 ㅋㅋㅋ\n삼청동으로 이전했다는 소식은 알고 있었지만\n이렇게 우연히 찾게 될 줄은 ㅎ.ㅎ\n예쁘고 탐나는 것 참 많은 곳..\n아이스크림 먹으면서 열 좀 식히다가\n논픽션 쇼룸을 와보았다.\n논픽션 삼청&기프트샵\n서울특별시 종로구 북촌로5길 84 1,2층\n꽤나 맘에 드는 향 발견\nH는 요거 하나 사가고 나는 고민을 좀...\n자취 시작하고 사고 싶은 거 냅다 바로 사는 버릇 확실히 고침\nㅋㅋㅋㅋㅋㅋ ^^ 알뜰한 살림꾼이다 이거야 ~\n2층 매장의 통창뷰가 아주 좋았습니다 -\n에쁘구만 !\n#광화문미진 웨이팅 걸어두고 넘 더워서 교보문고로 피신.\n새로운 책들 파밍하고 뜬금 퀴즈책을 구매했다 ㅋㅋ\n피의게임3 달리고 있던 시즌이라 머리 쓰는 거에 맛들림..\n퀴즈 풀면서 기다리다가 러브버그도 목격하고.. (심한욕)\n대기가 엄청 많았는데 금방금방 빠져서 40분 정도 기다렸다.\n호오 의외로 돈까스와 보쌈이 아주 맛있었다 ㅎㅎㅎ\n소바는 면이 넘 부드러워서 (난 뻣뻣한 걸 좋아함) 쏘쏘\n배터지게 먹고 뮤지컬 보러 세종문화회관으로 고고\n여름 구름\n아오 더워 진짜 여름 너무 싫어어어어ㅓ어어ㅓㅏㅓ\n박효신쓰의 팬텀\n어케 H가 티켓을 구해줘서 보러오게 되었다.\n전전날 공연은 컨디션이 좀 안 좋았다고 해서 걱정했는데\n이날은 걱정이 무색할 정도로 완벽했던 박효신쓰\n생각보다 무대 퀄리티도 좋았고 재밌었다 ~\n그렇게 6월 한 달 동안 2키로가 훅 쪄버린 나.\n늘어난 2키로에 1키로를 더해 3키로 빼기 여정 시작..\n하하하하 !\n-\n그 와중에 최근 종아리 관리에 시간과 돈 빡시게 쓰고 있었는데\n드디어 효과가 눈에 보이는 느낌쓰..\n내 인생에서 지금이 다리 제일 얇아보임 ㅋㅋ\n사실 둘레가 많이 줄지는 않았는데, 걍 그래 보임.\n6월 끝이요 !\n태그\n#아가젤라또\n#르메르필트포춘\n#르메르네트백\n#소이빙수\n#쿠시카츠쿠시토라\n#카페라포르\n#파파라구\n#키로베이커리\n#서랍\n#그레이맨션\n#광화문미진\n공감 19\n이 글에 공감한 블로거 열고 닫기\n댓글 18\n이 글에 댓글 단 블로거 열고 닫기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 13:34:00','관련 정보가 없습니다.'),
(8,'223944078199','열매달 이틀','서울특별시 마포구 대흥로 175 4동 1층 106호',37.5555,126.943,'국내\n[서울/경기] DAY 2_뜨개 투어(열매달이틀/솜솜뜨개)\n체 ・ 2025. 7. 23. 13:36\nURL 복사 이웃추가\n본문 기타 기능\n뜨개투어 둘째 날\n여기저기 다니려면 주차가 불편할 것 같아서\n차는 경복궁 주차장에 두고\n버스 타고 이동했다\n열매달 이틀\n서울특별시 마포구 대흥로 175 4동 1층 106호\n오늘의 첫 번째 장소는 열매달 이틀\n버스 내려서 한 골목만 들어가면 있어서\n차 없이 방문하기도 쉬웠다\n귀여운 스와치\n아람 콘사 색상이 다 예뻤다\n성분 좋고 색상 예쁜 실 많았지만\n집에 사둔 콘사가 너무 많아서\n눈에만 담고 오기\n매장 안 중앙 테이블에 보빈에 감긴 실 들이\n촤라락 정리되어 있어서 색상 비교하기가 좋았다\n수박색 귀여워\n(또 톤그로 색상만 콕콕 집어 내는 나)\n포토존도 있구요\n요렇게 두 가지 위시리스트에 기록!\n문의드릴 때만 답변해 주시는 자유로운 분위기라\n편하게 구경할 수 있었음!\n솜솜뜨개\n서울특별시 마포구 잔다리로9길 4-2 단독주택\n예약\n또 버스를 타고 이동\n그래도 두 매장은 크게 멀지 않아\n같은 날 일정에 넣기 적당\n골목 안에 있지만 찾기 쉬운 편이고\n문을 열면 사장님들(?)이 상냥하게 맞아주신다\n일어서서 계속 뜨개하고 계시고\n질문에 친절하게 답해주시고!\n수플레,, 넘 기여버,,\n뜰까 말까 고민했던 리모네 스웨터 실물로 만나보기\n아이코드 마무리 통통해서 귀엽다\n예뻐서 찍었는데 이게 무슨 실일까 ^^...\n이번 방문 목적은 러스크 구매!\n핫핑크색? 귀여워서 사고 싶었는데\n떠도 안 입을 거 같아서 무난한 색으루,,\n실버 그레이 예뻤는데 그레이 색상 너무 많이 사둬서;\n다른 색상 골랐음!\n프빌은 예전에 구매해서 가디건 떠보고 감동 먹음\n왜 솜솜뜨개 콘사 인기 많은지 알게 됨...\n세탁 매직,, 진짜 매직,,,\n위에 이름 몰랐던 실은 쉬폰인가보다\n얼마나 마음에 들었으면 두 번이나 찍었어\n브라운 색상 so cute,,\n내가 입으면 칙칙해지는 색이지만\n모어땨용 좋으면 입는 거지\n러스크 두 콘 골라서 결제 완\n개인적으로 솜솜 분위기가 마음에 들어서\n다음 번 서울 방문 때 또 갔숩니당 헤헤\n그리고 아침에 마신 티는 진즉에 다 써먹은 내 체력.\n솜솜 바로 앞에 있는 카페에서 아메리카노 수혈ㄱ\n제가 아메리카노 감별사인데요, 드셔도 됩니다!\n농담이고요 힘들어서 맛있었을 수도 있음요\n암튼 여기서 실토크 하다가,,\n귀인이가 산 수플레 넘 맘에 들어서,,\n다시 솜솜 뛰어 들어가서 나도 삼 ^^...\n서울 기념품 얼마어치 사냐?\n그리고 시골쥐는 비에 젖어서\n비에 쫄딱 젖은 시골쥐가 되었답니다...\n이렇게 얼굴에 직방으로 비 맞는 것도\n초딩 이후로 처음 같아요...\n사연 있는 여성 되기 완.\n그나저나 추가 구매한 수플레 못 찍어서 아쉬웠는데,\n이렇게 사진으로 남겼었구나 ^^......\n경복궁에서는 차 타고 조금 멀리 가야 있는 숙소,,\n서울 트래픽 잼 장난 없네요^____^\n운전해 준 귀인이 넘 고생했샤,,\n숙소 도착하고 치킨도 시켜 먹고 잘 놀다가\n불미스러운 일 발견\n오늘 날짜로 각인 부탁드렸는데,\n나를.. 2015년으로 회귀... 시켜주심..\n주말 지나고 연락드려서 여차저차 교환 성공,..!\n씻고 뽀송한 상태로 수다 떨면서 뜨개 하면\n얼마나 행복하게요\n그러다 막막콘 티켓까지 구하면\n얼마나 더 행복하게요?\n히히🩵\n내일도 계속되는 뜨개 투어\n마지막날 방문한 곳들도 넘 좋았따 !\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#뜨개투어\n#열매달이틀\n#솜솜뜨개\n공감 4\n이 글에 공감한 블로거 열고 닫기\n댓글 1\n이 글에 댓글 단 블로거 열고 닫기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 13:36:00','관련 정보가 없습니다.'),
(9,'223944132046','정약용펀그라운드 유스호스텔','경기도 남양주시 조안면 북한강로 881',37.596,127.337,'Grace Knitt\n카페 ;) 대너리스 + 정약용펀그라운드\ngrace knit ・ 2025. 7. 23. 14:19\nURL 복사 이웃추가\n본문 기타 기능\n지난 주\n#남양주시공유학교 #정약용펀그라운드\n유익한 수업이 있어\n큰 아이가 참여했어요.\n‘환경지킴이 유투브’\n평소 환경에 관심이 많은 아이라\n적합하겠다 싶어 신청했는데\n수업확정이 되어 기분이 좋아요~\n숙박형프로그램이라 1박을 하고 온다니\n아이도 엄마도 즐거운 수업이 될 듯 합니다\n주말오전이라 길이 막힐까 걱정했는데\n비가 많이 와서인지 새로 생긴 고속도로 덕분인지\n30분만에 가볍게 도착했어요~\n50m\n© NAVER Corp.\n정약용펀그라운드 유스호스텔\n경기도 남양주시 조안면 북한강로 881\n아이가 어릴때 코코몽팜빌리지에 종종 왔었는데\n그 아이가 청소년이 되어 똑같은 장소에 오다니..\n감회가 새롭습니다.\n펀그라운드는 청소년들을 위한 문화복합공간으로\n남양주시에는 6개지소가 있더라구요.\n그렇지만 실질적으로 개인적으로 이용은 잘 안하게 되었는데\n이번에 와보니 정약용펀그라운드는 특히나 유스호스텔까지 있어\n규모가 상당해 보였습니다.\n다산의 도시 남양주라 정약용 선생님의 이름을 붙여진 곳은\n조금 더 의미가 있는 곳처럼 느껴집니다.\n상시 다양한 프로그램도 진행중인듯 하니\n지역주민들이 활용하기에 너무 좋은 듯 합니다.\n요즘 지자체에서 질 좋은 프로그램을 시민들이 접할 수 있도록\n많은 노력을 하고 있는 듯 해요.\n펀그라운드 홈페이지에 자세히 안내되어 있으니\n혜택 꼭 챙겨보시길 바랍니다.\n남양주 펀그라운드\n존중받는 청소년, 행복한 청소년”실현하는 펀그라운드 펀그라운드는 청소년전용시설로 남양주시 청소년이 존중 받고 행복한 청소년으로 성장하는 공간입니다.\nwww.funground.or.kr\n여기까지 왔으니 홍수로 불어난 물구경 하러 근처 카페를 가봅니다.\n1분거리에 #카페대너리스 가 있네요!\n지하1층부터 3층까지 이루어져 있는데 분위기가 고풍스럽고 멋지네요\n지하는 강과 어우러진 자연을 가까이 접하기 좋다.\n1층은 출입구와 오더하는 곳이 있어 사람이 많을 수 있지만 모던한 인테리어로 가장 환하고 강도 잘보이고 분위기도 좋아요.\n2층은 오픈콘크리트와 엔틱한 분위기\n3층은 더욱 고풍스러운 분위기\n커피도 적당히 먹을만 했어요.\n아침 공복이라 혈당이슈로 빵을 못먹은게 아쉽지만\n내일 와서 먹어야지 다짐하고\n라떼를 마셔봅니다.\n바리스타를 배우며 알게된것인데\n제가 원하는 진한 라떼는 카푸치노였고\n라떼는 상대적으로 우유가 많이 들어가 상대적으로 싱거울 수 밖에 없어요.\n진한 라떼를 맛있는 라떼라고 생각하던 일반 소비자 입장에서는\n여전히 라떼와 카푸치노의 차이를 얼마나 많은 분들이 알 수 있을까요.\n대너리스 라떼도 제가 원하는 라떼보다는 싱거웠지만\n일반적인 라떼로는 충분하다는 말을 하고 싶어서\n서론이 길었습니다…\n커피 한모금 하더니 신랑이 갑자기\n‘대너리스…’ 드라마 여왕 이름인데\n아…그 드라마 이름이 뭐더라?\n‘용의 눈물!’\n뭐? 언제적 용의눈물이야!! ㅋㅋㅋㅋㅋ\n한바탕 웃음이 났습니다.\n제가 생각해도 용의눈물은 너무 심했어요.\n유동근 아저씨가 나왔었던 90년대 사극이였던거 같은데\n‘왕좌의 게임’이랑 ‘용의 눈물’\n어디에 접점을 둬야할지 난감합니다 ㅋㅋㅋ\n그렇게 둘째와 남편과 한바탕 웃음도 지어보고\n살뽀시 뜨개도 꺼내어 봅니다만…\n실내는… 너무 예뻤지만\n전국에 호우경보로 난리가 났던 상황이라\n습함을 잡기위해 너무 추웠고\n배관냄새인지 오래된 건물의 습습한 냄새가 엄습해\n후각이 예민한 저와 둘째아이는\n오래 앉아있기 힘들었어요.\n그래도 이뻤다.\n#대너리스 분위기 너무 좋고 야외도 예뻐서\n선선하고 좋을때 재방문 하고 싶어요!\n50m\n© NAVER Corp.\n카페 대너리스\n경기도 남양주시 조안면 북한강로 914\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#남양주시공유학교\n#정약용펀그라운드\n#카페대너리스\n#대너리스\n공감\n이 글에 공감한 블로거 열고 닫기\n댓글 1\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 14:19:00','관련 정보가 없습니다.'),
(10,'223944138670','하록수림','경기도 양평군 옥천면 용천로219번길 21 가동, 나동',37.5422,127.496,'나도먹었다\n[양평/카페] 양평 여행하며 들르기 좋은 숲 뷰 넓은 카페 하록수림\n독솔이 ・ 2025. 7. 23. 14:24\nURL 복사 이웃추가\n본문 기타 기능\n여행중 카페고르는 것 너무나 고민\n요새는 좋은 목이고 뭐고 방방곡곡\n멋들어진 막들어진 카페가 많기도 하지요.\n양평여행중 들른카페\n하록수림 후기입니다🤗\n하록수림\n목~화 11:00 ~ 20:00\n매주 수요일 휴무(공휴일 정상영업)\n주차쾌적\n화장실쾌적\n50m\n© NAVER Corp.\n하록수림\n경기도 양평군 옥천면 용천로219번길 21 가동, 나동\n예약\n도착하자마자 너른 잔디밭에\n우선 마음 힐링하고 갑니다.\n흔들그네 못지나치는 어른이들\n신나게 스윙한번 타주고요\n카페에는 음료 외에도 휘낭시에 등등\n디저트류도 많이 있었어요.\n저희는 1인1음료 + 빙수 주문했읍니다.\n귀여움 포인또로\n강아지 전용메뉴와\n뜨개인형도 있었어요ㅎㅎ\n반려동물친화 & 예스키즈존👍\n바깥 정원뿐 아니라 실내에도 화분들이 있어\n실내 분위기도 넘 차분하고 좋았어요!\n1층 좌석과 숲뷰~\n2층 좌석은 바깥으로 통해서 계단을 올라가야해요\n화장실은 남/여 따로!\n1층과 2층 각각 있었고\n아기의자도 있었어요.\n2층으로 향하는 길\n야외좌석도 있어서\n날이 덥지 않을 땐 밖에 앉는 것도\n힐링 그 잡채일 듯합니다.ㅎㅎ\n2층 좌석 또한 통창 숲뷰에\n가슴뻥뚫려주고요,\n보이는 좌석 외에도\n안쪽에 룸 공간으로 분리된 단체석도 있었어요.ㅎㅎ\n친구들과 방문해서 오손도손 대화나누기 너무 편했고,\n음료와 빙수도 아쥬 맛났습니다.👍\n양평 한적하고 쾌적한 카페 찾으신다면\n하록수림 추천!\n태그\n#양평맛집\n#양평여행\n#양평카페\n#양평카페추천\n#양평카페정원\n#양평정원카페\n#하록수림\n#양평하록수림\n공감 6\n이 글에 공감한 블로거 열고 닫기\n댓글 쓰기\n이 글에 댓글 단 블로거 열고 닫기\n블로그 보내기\n카페 보내기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 14:24:00','관련 정보가 없습니다.'),
(11,'223944168986','바늘이야기 파주직영점','경기도 파주시 탄현면 법흥로 100-1',37.7766,126.706,'국내\n[서울/경기] DAY 3_뜨개 투어(바늘이야기 파주직영점)\n체 ・ 2025. 7. 23. 14:47\nURL 복사 이웃추가\n본문 기타 기능\n뜨개 투어 마지막 날\n오늘은 아침부터 바쁩니다\n바빠서 아침은 맥도날드 드라이브스루로\n대강 스루 할게요ㅋ\n바늘이야기 파주직영점\n경기도 파주시 탄현면 법흥로 100-1\n서울에서 대중교통으로 가능은 하나\n내 체력으로는 쉽지 않은, 파주 바늘이야기.\n귀인이가 운전해 줘서 엄청 쉽게 갔다네요~\n아리각또,, ㅠㅠ\n오픈(10시) 전에 도착해서 조금 기다리기\n문열어주삼요\n뜨개인이라면 다 아는 바늘이야기 콘사월\n인증샷 찍어 주시고\n입구 오른편으로 이렇게 실과 바늘 쇼핑 가능\n샘플 작품도 연희점만큼 다양하게 준비되어 있음\n2층도 가봅니다\n시원하게 1층이랑 연결되어 있음\n3층엔 이렇게 빈백에 반 누워서 뜨개 가능\n빈백 맞은편에 있는 테이블에서는\n충전기 사용도 가능해서(콘센트 o)\n영상 보며 뜨개 하실 분들은 3층 추천!\n귀여운 스초생,,\n마시멜로 동동 띄운 핫초코랑\n바게트도 귀여워\n카페 통창 앞으로는 잔디밭이 펼쳐져 있어서\n내가 강아지였다면 매우 행복했을 것 같았슨,,\n아메리카노 한 잔씩이랑 스콘\n티코스터가 단추인 게 너무 컨셉츄얼하구 기여븜\n네, 제가 아메리카노 감별사인데요!\n네! 이상입니다!\n2층 카페 카운터 바로 앞에 있는 좌석에 앉았는데\n해가 쨍쨍하게 들어와서 기분이 좋았다\n분명 어제저녁에는 비 맞은 생쥐 꼴이었는데,,\n난 어딜 가나 항상 마지막 날 날씨가 그렇게 좋더라?\n약 올리냐고\n언니 뭐해요?\nㄴ뜨개질 해.\n나잖아?\n근데 뜨개질 아니고 뜨개.\n뜰 의향 너무너무 있는 포그 가디건\n양배추 색깔까지 완전 귀엽따 !\n이거 뜨려고 사둔 모헤어도 있서\n털이 개날려서 그렇지\n오른쪽 해리 테리어 티슈케이스는\n나 이사 가면 떠서 쓰려고!\n이사계획은 물론 없음 ^___^ !\n마음에 드는 가방도 자유롭게 착용해보구요\n제 최애 구역으로 정하겠습니다\n언젠가 크렘캐시울 한 번은 써 볼게요\n김대리님 뜨개 책(몇 번째 책이더라) 출간하고\n그 안에 크렘캐시울로 뜰만한 도안들이 있어서\n다들 엄청 뜨셨는데, 난 책만 구입해두고\nㅈㅅ동 대표 뒷북쟁이라서 아직 안 떠봄 ^^..\n라쿤 메리노는 아마 집에 사둔 게 있을 거예요\n진짜 어디 처박아 뒀는지 기억도 안남\n우리 집 물류창고 만들기 아티스트\n리갈울,,,\n이걸로 크렘므 스웨터 뜨는 거져?\n8월 상여금만 기다리고 있습니다 나\n무슨 색 할까? 빨강? 브라운?\n아임울도 너무 좋지,,\n팃타에서 어떤 분 뜨고 계신 실이 넘 예뻐서\n난생 첨으로 그 앱에서 쪽지 기능을 사용해서 여쭤봄\n같은 낙양모사에서 나온 실이었는데, 여기 실이 참 예뻐요\n아까 그 티슈케이스 뜨는 해리실,,\n넘모 기엽자너\n뜨개 실컷 하다 가고 싶었지만\n우리는 파주에서 양재까지 달렸다가\n잠실 가야 해서 얼른 일어남..\n정말 기적의 코스시다....\n저작자 명시 필수\n영리적 사용 불가\n내용 변경 불가\n태그\n#뜨개투어\n#바늘이야기\n#바늘이야기파주\n#바늘이야기파주직영점\n공감 3\n이 글에 공감한 블로거 열고 닫기\n댓글 3\n이 글에 댓글 단 블로거 열고 닫기\nKeep 보내기\n메모 보내기\n기타 보내기 펼치기\n\n\n\n\n\n인쇄','2025-07-23 14:47:00','모헤어: 있음  \n충전기: 없음  \n좌석: 없음'),
(12,'223944243700','그릭 수블라키','37 Trần Quang Khải, Lộc Thọ, Nha Trang, Khánh Hòa 650000 베트남',12.2333,109.196,'세계여행\n2025 mar. 나짱 여행 #8 시타딘 베이 프런트 나트랑 그릭수블라키 소품샵 카페 헬렌스파 앙반미 척칩 두리안 갈란갈 깜란공항 티웨이 tw156 청주공항\n여행하는 쪼쪼 ・ 2025. 7. 23. 15:43\nURL 복사 이웃추가\n본문 기타 기능\n위치시타딘스 베이프런트 나트랑\n7박 9일 베트남 나트랑 여행 🌴\nNHA TRANG | VIETNAM | 2025 mar.\n3월 4일 ~ 3월 12일\n📍day 7 - 다이아몬드 베이 호텔 탐스파 옌 커피 앤 모어 척칩\n2025 mar. 나짱 여행 #7 다이아몬드 베이 호텔 시타딘 베이 프런트 나트랑 탐스파 홈 나이 옌 커피 앤 모어 척칩 앙 반미 미미 프루츠\n7박 9일 베트남 나트랑 여행 🌴 NHA TRANG | VIETNAM | 2025 mar. 3월 4일 ~ 3월 12일 ?...\nblog.naver.com\n[ 힐링 바가지 3월의 나짱 여행 📍day 8-9 ]\n시타딘 베이 프런트 나트랑 Citadines Bayfront Nha Trang\n그릭 수블라키 Greek Souvlaki\n소품샵 Nhà Hè Handmade &recycles\n카페 AIMÉE Coffee Shop\n헬렌 스파 Helen Spa\n앙 반미 Ăn Bánh Mì\n척칩 Khoai lang lắc Chúc Chíp\n두리안 노점\n갈란갈 Nhà hàng Galangal\n깜라인 국제공항 Cam Ranh international airport\n청주공항 Cheongju airport\n눈뜨자마자 일출시간인 것 같아서\n창밖으로 빼꼼 내밀고 바다 구경을 했다 😃\n구름은 많았지만 건물에 딱 걸렸지만\n바다도 예쁘고 일출도 예뻤다\n밖에 나가서 구경할 걸 그랬네\n남편은 일어나려면 오만 년이니까 다시 눕자\n밤에 공항에 가야 해서 하루가 엄청 길 예정 😭\n드디어 일어난 남편이랑 조식 먹으러 갑니다\n전날 체크인할 때 받은 쿠폰 잘 챙기고\n2층 레스토랑으로 내려갑니당\n조식당 공간도 엄청 넓고 좌석도 많았다\n분짜도 만들어 먹을 수 있고\n미니 반미도 있고 샐러드에 치즈에 ♥️\n내 사랑 브리 치즈도 있고 행복이야\n준비되어 있는 커피랑 차 외에\n코코넛 커피도 무료로 주문할 수 있었다\n직원에게 요청하면 자리로 만들어줬다\n음식도 괜찮았고 맛있는 거 많았는데\n밤에 공항으로 가야 해서 내일은 못 먹는다니 🥹\n과일이랑 디저트까지 배 터지게 먹었다\n배부르니까 산책 가야쥬\n집에 가는 날에 날씨가 제일 좋아 😏\n호텔에서 길만 건너면 전용 비치가 있었다\n직원분이 선베드에 수건도 깔아주고\n파라솔 위치도 잡아주고 서비스 👍\n산책하러 나와놓고 뜨거워서 일단 누움 🤭\n햇빛이 세서 바닷물도 미지근할 것 같았는데\n아직 3월이라 그런가 바닷물은 시원했다\n파도 밀려오는 거 신나게 구경하고 있었더니\n파도를 찍는 나를 찍은 남편 😉\n위치도 괜찮고 숙소 컨디션도 좋고\n다음에도 시타딘 또 와야지 히히\n귀요미 미쳐부러 ♥️\n누워있다가 그새 잠든 우리 집 아죠씨 😂\n파도 소리도 좋고 바람도 좋고\n이대로 하루만 더 있었으면 좋겠네 유\n집에 가야 해서 미련 철철 흐름\n들어가는 길에 헬스장 들르기\nㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n우리 집 큰아들입니다 🤭\n유산소랑 웨이트 존이 나뉘어 있어서\n운동하는 공간도 쾌적했다\n운동화 챙겨가 놓고 헬스장은 구경만 해요 🤣\n아직 이른 시간이라 수영장에 아무도 없길래\n얼른 올라가서 옷 갈아입고 내려왔다 키키\n선베드만 있고 파라솔은 없어서\n그늘에 있는 자리는 금방 자리가 찼다\n조식 시간 끝나면 사람들 몰리니까 얼른 오는 게 좋을 듯\n밤에도 차가웠는데 햇빛 쨍한 낮에도 세상 시원 🥶\n그래도 뛰어들어야지 풍덩풍덩\n놀다 보면 햇빛이 뜨거워서 놀을 만 했다 🏊‍♀️\n암 튜브 없이는 못 살아 😃\n바닷가 쪽 자리에 자리를 잡고\n챙겨온 고구마튀김이랑 간식도 먹고\n누워서 뒹굴뒹굴 한참을 누워있었다 😂\n점점 머리 위로 햇빛이 쏟아져서 누워있다가 튀튀\n태양을 피할 공간이 부족한 게 조금 아쉽네\n어디서나 잘 자는 우리 집 아죠씨 👍\n방에 들어와서 씻고 나갈 준비 완료\n샴푸 마사지 받을 거라 머리는 안 감는다 🤭\nㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n나짱 와서 내 손으로 머리 한 번도 안 감음\n물놀이했더니 출출하니까 맛난 거 먹고\n카페 가서 커피도 한잔해야겠다\n나짱 곳곳에 여러 이름으로 있는 그릭수블라키\n여기 매장이 제일 넓고 깔끔한 편이다\n이번엔 랩으로만 두 개 먹기로 했다\n커다란 맥주가 만 오천 동밖에 안 합니다\n맥주 인심 제일 좋은 그릭수블라키 ♥️\n양고기는 확실한데 나머지 하나는 뭐였더라\n치킨이었나 돼지고기였나 아무튼 맛있음 😉\n차지키 소스 사랑해요 ♥️\n둘 다 차지키 소스인 걸 보니 양고기랑 돼지 같다!\n치킨도 괜찮고 소고기도 맛있다\n나트랑 오면 한 번쯤은 꼭 먹어보셔용\n그릭 수블라키\n37 Trần Quang Khải, Lộc Thọ, Nha Trang, Khánh Hòa 650000 베트남\n카페 가던 길에 잠깐 들른 소품샵 냐헤(?)\nNhà Hè Handmade &recycles\n2층은 카페인 것 같고 1층이 소품 숍이었다\n뜨개 인형 액세서리 마그넷 등등\n엄청 다양한 상품이 있었다\n귀여운 거 천지다 천지야 😃\n자개로 된 스푼이랑 포크도 있고\n그릇이랑 양말, 옷이랑 가방도 있고\n볼게 많아서 꼼꼼히 보려면 한참 걸릴 것 같았다\n가격대는 저렴하지는 않았지만\n선물용으로 괜찮은 것들이 많았다\n그릇 쓸어 담고 싶었지만 위탁이 없어 그냥 가유 😭\nNhà Hè Handmade &recycles\n120/8 Nguyễn Thiện Thuật, Tân Tiến, Nha Trang, Khánh Hòa 650000 베트남\n강아지 있다고 해서 가려고 찜해뒀던 카페인데\n카페가 단독으로 있는 게 아니라\n게스트 하우스 1층 공간에 팝업처럼 있는 거였다 허허\n더울 것 같아서 다른데 갈까 하다가\n사장님이랑 눈 마주쳐서 들어와서 앉음 😂\n선풍기도 시원하게 틀어주심 키키\n아이스 아메리카노랑 박시우\n커피 두 잔에 65,000동이었다 👍\n갑자기 짠하고 나타난 귀요미 😃\n괴롭히지 말라구 아죠씨야 😏\n야무지게 밀어버린 닭발 미용에\n강아지 샴푸 냄새 폴폴 났다\n표정이 너무 아련해 🤣\n맛난 커피도 먹고 멍멍 파워 충전했다\nAIMÉE Coffee Shop\n73/6 Trần Quang Khải, Lộc Thọ, Nha Trang, Khánh Hòa 650000 베트남\n댕댕이랑 더 놀고 싶었지만 너무 더워 🥵\n마사지 예약해둔 시간 다가와서\n숙소 잠깐 들렀다가 다시 나가기로 했다\n화장실 얼른 갔다가 마사지 받으러 갑니다\n다이아몬드 베이 호텔에서 엘리베이터 때문에\n매번 고생하다가 시타딘 왔더니 엘베 풍년이야\n원할 때 바로바로 탈 수 있었다 ㅋㅋㅋㅋ\n이번 여행에서 제일 많이 온 헬렌 스파 😉\n척칩에 이어 여기도 직원이 알아보는 눈치다\n갖고 온 짐은 캐비닛에 보관하고\n핸드폰이랑 팁 줄 약간의 현금만 챙겼다\n족욕 먼저 하고\n오늘도 2층 우리 지정 스파룸 😂\n남편은 전신마사지 받고 나는 샴푸랑 머리 마사지\n동시에 같은 공간에서 받을 수 있어서 👍\n하루 종일 붙어있었으면서 안 떨어지려고\nㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n떨어져서 받을 때마다 해프닝들이 있어서 허허\n한공간에서 나란히 누워 받는 게 속 편하다\nHelen Spa - Massage Spa in Nha Trang 헬렌 스파_나트랑 마사지 스파\n122a Đ. Hồng Bàng, Tân Tiến, Nha Trang, Khánh Hòa 650000 베트남\n앙반미 들러서 비행기에서 먹을 반미랑\n플레인 반미도 5개 샀다 🤤\n진공포장까지 해줘서 들고 오기 좋았다\n냉동실에 넣어뒀다가 반미 먹고 싶을 때\n하나씩 꺼내서 소고기랑 계란 넣고 만들어 먹었다\n앙반미\n99 Đ. Hồng Bàng, Tân Tiến, Nha Trang, Khánh